def family_shapes(name: str, **overrides: tuple[int, ...]) -> dict[str, tuple[int, ...]]:
    shapes = {key: DEFAULT_SHAPE for key in FAMILY_KEYS[name]}
    shapes.update(FAMILY_OVERRIDES.get(name, {}))
    shapes.update(overrides)
    return shapes
